{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket has no account-independent bucket-level controls preventing public ACLs or policies. Because its ACL is variable-driven, an unsafe value could otherwise expose bucket data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "Without versioning, accidental deletion or overwrite of objects cannot be readily reversed, increasing the impact of mistakes or destructive activity."
    },
    {
      "check_id": "CKV_AWS_18",
      "title": "S3 server access logging is disabled",
      "resource": "aws_s3_bucket.bucket_2",
      "severity": "MEDIUM",
      "explanation": "The bucket does not record access requests, reducing visibility for investigations and detection of unauthorized access."
    }
  ],
  "patched_code": "data "aws_caller_identity" "current" {}

resource "aws_s3_bucket" "bucket_2" {
  bucket = "roger-bucket-2"
  acl    = var.bucket_acl

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        kms_master_key_id = aws_kms_key.my_key.arn
        sse_algorithm     = "aws:kms"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "bucket_2" {
  bucket = aws_s3_bucket.bucket_2.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket" "bucket_2_access_logs" {
  bucket = "roger-bucket-2-access-logs"

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_public_access_block" "bucket_2_access_logs" {
  bucket = aws_s3_bucket.bucket_2_access_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_versioning" "bucket_2_access_logs" {
  bucket = aws_s3_bucket.bucket_2_access_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_policy" "bucket_2_access_logs" {
  bucket = aws_s3_bucket.bucket_2_access_logs.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "S3ServerAccessLogsPolicy"
        Effect = "Allow"
        Principal = {
          Service = "logging.s3.amazonaws.com"
        }
        Action   = "s3:PutObject"
        Resource = "${aws_s3_bucket.bucket_2_access_logs.arn}/access-logs/*"
        Condition = {
          ArnLike = {
            "aws:SourceArn" = aws_s3_bucket.bucket_2.arn
          }
          StringEquals = {
            "aws:SourceAccount" = data.aws_caller_identity.current.account_id
          }
        }
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.bucket_2_access_logs]
}

resource "aws_s3_bucket_logging" "bucket_2" {
  bucket        = aws_s3_bucket.bucket_2.id
  target_bucket = aws_s3_bucket.bucket_2_access_logs.id
  target_prefix = "access-logs/"

  depends_on = [aws_s3_bucket_policy.bucket_2_access_logs]
}
",
  "fix_summary": "Added a full S3 Public Access Block and enabled versioning for the original bucket. Added a private, encrypted, versioned logging bucket with a source-restricted delivery policy, then enabled server access logging for the original bucket."
}
